/**
 * SplitButton's lawful variant × tone cells, and only those: the grid the web types as
 * `LawfulVariants`. `lawful` lists them in grid order.
 */
enum class PMSplitButtonAppearance(
    val value: String,
    val variant: PMSplitButtonVariant,
    val tone: PMSplitButtonTone,
) {
    SolidAccent("solid/accent", PMSplitButtonVariant.Solid, PMSplitButtonTone.Accent),
    SoftAccent("soft/accent", PMSplitButtonVariant.Soft, PMSplitButtonTone.Accent),
    OutlineNeutral("outline/neutral", PMSplitButtonVariant.Outline, PMSplitButtonTone.Neutral),
    OutlineAccent("outline/accent", PMSplitButtonVariant.Outline, PMSplitButtonTone.Accent),
    ;

    companion object {
        /** Every lawful cell, in grid order. */
        val lawful: List<PMSplitButtonAppearance> = listOf(
            SolidAccent,
            SoftAccent,
            OutlineNeutral,
            OutlineAccent,
        )

        /** The cell for a variant and a tone, or null when the grid excludes the pair. */
        fun of(variant: PMSplitButtonVariant, tone: PMSplitButtonTone): PMSplitButtonAppearance? =
            entries.firstOrNull { it.variant == variant && it.tone == tone }
    }
}

